   509→function emitMessageOfTheDay(msg, count) {
   510→  if (!msg || count == null) {
   511→    return;
   512→  }
   513→  // we keep a counter in local storage so we can
   514→  // enforce showing the MOTD to a person just once.
   515→  var mcount = localStorage.getItem('motd-count');
   516→  var showMessage = true;
   517→  if (mcount != null) {
   518→      mcount = parseInt(mcount);
   519→      if (mcount >= count) {
   520→        showMessage = false;
   521→      }
   522→  }  else {
   523→    mcount = 0;
   524→  }
   525→
   526→  if (showMessage) {
   527→    motdInfo(msg);
   528→    localStorage.setItem('motd-count', count.toString());
   529→  }
   530→}
